if (order.couponCode === code) return order; // 再送は何もしない
if (order.couponCode) throw new CouponAlreadyAppliedError(order.id);
// consumeUse と save を 1 つのトランザクションに入れる
db.exec('BEGIN');
try { /* consumeUse → save */ db.exec('COMMIT'); }
catch (e) { db.exec('ROLLBACK'); throw e; }

CREATE TABLE coupon_redemptions (
  order_id    TEXT PRIMARY KEY REFERENCES orders (id),
  coupon_code TEXT NOT NULL REFERENCES coupons (code)
);
